class Solution { private class Node{val next=arrayOfNulls<Node>(2);var count=0};private fun countLess(nums:IntArray,limit:Int):Int{val root=Node();var answer=0;for(value in nums){var node:Node?=root;for(bit in 15 downTo 0){if(node==null)break;val digit=value shr bit and 1;val bound=limit shr bit and 1;if(bound==1){answer+=node.next[digit]?.count?:0;node=node.next[digit xor 1]}else node=node.next[digit]};node=root;node.count++;for(bit in 15 downTo 0){val digit=value shr bit and 1;if(node!!.next[digit]==null)node.next[digit]=Node();node=node.next[digit];node!!.count++}};return answer};fun countPairs(nums:IntArray,low:Int,high:Int):Int=countLess(nums,high+1)-countLess(nums,low) }
